///   0. `[signer]` user
///   1. `[writable]` lb_pair
///   2. `[writable]` bin_array_bitmap_ext
///   3. `[writable]` reserve_x
///   4. `[writable]` reserve_y
///   5. `[writable]` user_token_in
///   6. `[writable]` user_token_out
///   7. `[]` token_x_mint
///   8. `[]` token_y_mint
///   9. `[writable]` oracle
///   10. `[writable]` host_fee_in
///   11. `[]` token_x_program
///   12. `[]` token_y_program
///   13. `[]` memo_program
///   14. `[]` event_authority
///   15. `[]` dlmm_program
#[derive(Clone, Debug)]
pub struct SwapCpiBuilder<'a, 'b> {
    instruction: Box<SwapCpiBuilderInstruction<'a, 'b>>,
}

impl<'a, 'b> SwapCpiBuilder<'a, 'b> {
    pub fn new(program: &'b solana_account_info::AccountInfo<'a>) -> Self {
        let instruction = Box::new(SwapCpiBuilderInstruction {
            __program: program,
            user: None,
            lb_pair: None,
            bin_array_bitmap_ext: None,
            reserve_x: None,
            reserve_y: None,
            user_token_in: None,
            user_token_out: None,
            token_x_mint: None,
            token_y_mint: None,
            oracle: None,
            host_fee_in: None,
            token_x_program: None,
            token_y_program: None,
            memo_program: None,
            event_authority: None,
            dlmm_program: None,
            amount_in: None,
            min_out: None,
            num_bin_arrays: None,
            __remaining_accounts: Vec::new(),
        });
        Self { instruction }
    }
    /// Transaction signer and token owner
    #[inline(always)]
    pub fn user(&mut self, user: &'b solana_account_info::AccountInfo<'a>) -> &mut Self {
        self.instruction.user = Some(user);
        self
    }
    /// DLMM lb_pair for swap
    #[inline(always)]
    pub fn lb_pair(&mut self, lb_pair: &'b solana_account_info::AccountInfo<'a>) -> &mut Self {
        self.instruction.lb_pair = Some(lb_pair);
        self
    }
    /// Bin array bitmap extension for swap (pass DLMM program ID if unused)
    #[inline(always)]
    pub fn bin_array_bitmap_ext(
        &mut self,
        bin_array_bitmap_ext: &'b solana_account_info::AccountInfo<'a>,
    ) -> &mut Self {
        self.instruction.bin_array_bitmap_ext = Some(bin_array_bitmap_ext);
        self
    }
    /// Pool token X reserve for swap
    #[inline(always)]
    pub fn reserve_x(&mut self, reserve_x: &'b solana_account_info::AccountInfo<'a>) -> &mut Self {
        self.instruction.reserve_x = Some(reserve_x);
        self
    }
    /// Pool token Y reserve for swap
    #[inline(always)]
    pub fn reserve_y(&mut self, reserve_y: &'b solana_account_info::AccountInfo<'a>) -> &mut Self {
        self.instruction.reserve_y = Some(reserve_y);
        self
    }
    /// User ATA for swap input token
    #[inline(always)]
    pub fn user_token_in(
        &mut self,
        user_token_in: &'b solana_account_info::AccountInfo<'a>,
    ) -> &mut Self {
        self.instruction.user_token_in = Some(user_token_in);
        self
    }
    /// User ATA for swap output token
    #[inline(always)]
    pub fn user_token_out(
        &mut self,
        user_token_out: &'b solana_account_info::AccountInfo<'a>,
    ) -> &mut Self {
        self.instruction.user_token_out = Some(user_token_out);
        self
    }
    /// Token X mint for swap
    #[inline(always)]
    pub fn token_x_mint(
        &mut self,
        token_x_mint: &'b solana_account_info::AccountInfo<'a>,
    ) -> &mut Self {
        self.instruction.token_x_mint = Some(token_x_mint);
        self
    }
    /// Token Y mint for swap
    #[inline(always)]
    pub fn token_y_mint(
        &mut self,
        token_y_mint: &'b solana_account_info::AccountInfo<'a>,
    ) -> &mut Self {
        self.instruction.token_y_mint = Some(token_y_mint);
        self
    }
    /// Oracle account for swap
    #[inline(always)]
    pub fn oracle(&mut self, oracle: &'b solana_account_info::AccountInfo<'a>) -> &mut Self {
        self.instruction.oracle = Some(oracle);
        self
    }
    /// Host fee account for swap A (pass DLMM program ID if unused)
    #[inline(always)]
    pub fn host_fee_in(
        &mut self,
        host_fee_in: &'b solana_account_info::AccountInfo<'a>,
    ) -> &mut Self {
        self.instruction.host_fee_in = Some(host_fee_in);
        self
    }
    /// SPL Token program for token X of swap
    #[inline(always)]
    pub fn token_x_program(
        &mut self,
        token_x_program: &'b solana_account_info::AccountInfo<'a>,
    ) -> &mut Self {
        self.instruction.token_x_program = Some(token_x_program);
        self
    }
    /// SPL Token program for token Y of swap
    #[inline(always)]
    pub fn token_y_program(
        &mut self,
        token_y_program: &'b solana_account_info::AccountInfo<'a>,
    ) -> &mut Self {
        self.instruction.token_y_program = Some(token_y_program);
        self
    }
    /// Memo program
    #[inline(always)]
    pub fn memo_program(
        &mut self,
        memo_program: &'b solana_account_info::AccountInfo<'a>,
    ) -> &mut Self {
        self.instruction.memo_program = Some(memo_program);
        self
    }
    /// DLMM event authority PDA for swap
    #[inline(always)]
    pub fn event_authority(
        &mut self,
        event_authority: &'b solana_account_info::AccountInfo<'a>,
    ) -> &mut Self {
        self.instruction.event_authority = Some(event_authority);
        self
    }
    /// Meteora DLMM program
    #[inline(always)]
    pub fn dlmm_program(
        &mut self,
        dlmm_program: &'b solana_account_info::AccountInfo<'a>,
    ) -> &mut Self {
        self.instruction.dlmm_program = Some(dlmm_program);
        self
    }
    #[inline(always)]
    pub fn amount_in(&mut self, amount_in: u64) -> &mut Self {
        self.instruction.amount_in = Some(amount_in);
        self
    }
    #[inline(always)]
    pub fn min_out(&mut self, min_out: u64) -> &mut Self {
        self.instruction.min_out = Some(min_out);
        self
    }
    #[inline(always)]
    pub fn num_bin_arrays(&mut self, num_bin_arrays: u8) -> &mut Self {
        self.instruction.num_bin_arrays = Some(num_bin_arrays);
        self
    }
    /// Add an additional account to the instruction.
    #[inline(always)]
    pub fn add_remaining_account(
        &mut self,
        account: &'b solana_account_info::AccountInfo<'a>,
        is_writable: bool,
        is_signer: bool,
    ) -> &mut Self {
        self.instruction
            .__remaining_accounts
            .push((account, is_writable, is_signer));
        self
    }
    /// Add additional accounts to the instruction.
    ///
    /// Each account is represented by a tuple of the `AccountInfo`, a `bool` indicating whether the account is writable or not,
    /// and a `bool` indicating whether the account is a signer or not.
    #[inline(always)]
    pub fn add_remaining_accounts(
        &mut self,
        accounts: &[(&'b solana_account_info::AccountInfo<'a>, bool, bool)],
    ) -> &mut Self {
        self.instruction
            .__remaining_accounts
            .extend_from_slice(accounts);
        self
    }
    #[inline(always)]
    pub fn invoke(&self) -> solana_program_error::ProgramResult {
        self.invoke_signed(&[])
    }
    #[allow(clippy::clone_on_copy)]
    #[allow(clippy::vec_init_then_push)]
    pub fn invoke_signed(&self, signers_seeds: &[&[&[u8]]]) -> solana_program_error::ProgramResult {
        let args = SwapInstructionArgs {
            amount_in: self
                .instruction
                .amount_in
                .clone()
                .expect("amount_in is not set"),
            min_out: self
                .instruction
                .min_out
                .clone()
                .expect("min_out is not set"),
            num_bin_arrays: self
                .instruction
                .num_bin_arrays
                .clone()
                .expect("num_bin_arrays is not set"),
        };
        let instruction = SwapCpi {
            __program: self.instruction.__program,

            user: self.instruction.user.expect("user is not set"),

            lb_pair: self.instruction.lb_pair.expect("lb_pair is not set"),

            bin_array_bitmap_ext: self
                .instruction
                .bin_array_bitmap_ext
                .expect("bin_array_bitmap_ext is not set"),

            reserve_x: self.instruction.reserve_x.expect("reserve_x is not set"),

            reserve_y: self.instruction.reserve_y.expect("reserve_y is not set"),

            user_token_in: self
                .instruction
                .user_token_in
                .expect("user_token_in is not set"),

            user_token_out: self
                .instruction
                .user_token_out
                .expect("user_token_out is not set"),

            token_x_mint: self
                .instruction
                .token_x_mint
                .expect("token_x_mint is not set"),

            token_y_mint: self
                .instruction
                .token_y_mint
                .expect("token_y_mint is not set"),

            oracle: self.instruction.oracle.expect("oracle is not set"),

            host_fee_in: self
                .instruction
                .host_fee_in
                .expect("host_fee_in is not set"),

            token_x_program: self
                .instruction
                .token_x_program
                .expect("token_x_program is not set"),

            token_y_program: self
                .instruction
                .token_y_program
                .expect("token_y_program is not set"),

            memo_program: self
                .instruction
                .memo_program
                .expect("memo_program is not set"),

            event_authority: self
                .instruction
                .event_authority
                .expect("event_authority is not set"),

            dlmm_program: self
                .instruction
                .dlmm_program
                .expect("dlmm_program is not set"),
            __args: args,
        };
        instruction.invoke_signed_with_remaining_accounts(
            signers_seeds,
            &self.instruction.__remaining_accounts,
        )
    }
}

#[derive(Clone, Debug)]
struct SwapCpiBuilderInstruction<'a, 'b> {
    __program: &'b solana_account_info::AccountInfo<'a>,
    user: Option<&'b solana_account_info::AccountInfo<'a>>,
    lb_pair: Option<&'b solana_account_info::AccountInfo<'a>>,
    bin_array_bitmap_ext: Option<&'b solana_account_info::AccountInfo<'a>>,
    reserve_x: Option<&'b solana_account_info::AccountInfo<'a>>,
    reserve_y: Option<&'b solana_account_info::AccountInfo<'a>>,
    user_token_in: Option<&'b solana_account_info::AccountInfo<'a>>,
    user_token_out: Option<&'b solana_account_info::AccountInfo<'a>>,
    token_x_mint: Option<&'b solana_account_info::AccountInfo<'a>>,
    token_y_mint: Option<&'b solana_account_info::AccountInfo<'a>>,
    oracle: Option<&'b solana_account_info::AccountInfo<'a>>,
    host_fee_in: Option<&'b solana_account_info::AccountInfo<'a>>,
    token_x_program: Option<&'b solana_account_info::AccountInfo<'a>>,
    token_y_program: Option<&'b solana_account_info::AccountInfo<'a>>,
    memo_program: Option<&'b solana_account_info::AccountInfo<'a>>,
    event_authority: Option<&'b solana_account_info::AccountInfo<'a>>,
    dlmm_program: Option<&'b solana_account_info::AccountInfo<'a>>,
    amount_in: Option<u64>,
    min_out: Option<u64>,
    num_bin_arrays: Option<u8>,
    /// Additional instruction accounts `(AccountInfo, is_writable, is_signer)`.
    __remaining_accounts: Vec<(&'b solana_account_info::AccountInfo<'a>, bool, bool)>,
}
